import{gateway,wrapLanguageModel}from"ai";function withUniqueCallIds(e,t){return wrapLanguageModel({model:resolved(e),middleware:uniqueCallIds(new Set(t))})}function resolved(e){return typeof e==`string`?(Reflect.get(globalThis,`AI_SDK_DEFAULT_PROVIDER`)??gateway).languageModel(e):e}function uniqueCallIds(e){return{specificationVersion:`v4`,wrapStream:async({doStream:t})=>{let{stream:n,...r}=await t();return{...r,stream:n.pipeThrough(renameRepeatedCalls(e))}}}}function renameRepeatedCalls(e){let t=new Map,n=new Set,introduce=n=>{let r=n;for(let t=2;e.has(r);t++)r=`${n}_${t}`;return e.add(r),r===n?t.delete(n):t.set(n,r),r},current=e=>t.get(e)??e;return new TransformStream({transform(e,t){switch(e.type){case`tool-input-start`:n.add(e.id),t.enqueue({...e,id:introduce(e.id)});return;case`tool-input-delta`:case`tool-input-end`:t.enqueue({...e,id:current(e.id)});return;case`tool-call`:{let r=n.delete(e.toolCallId)?current(e.toolCallId):introduce(e.toolCallId);t.enqueue({...e,toolCallId:r});return}case`tool-result`:case`tool-approval-request`:t.enqueue({...e,toolCallId:current(e.toolCallId)});return;default:t.enqueue(e)}}})}export{withUniqueCallIds};